const items = $input.all();

const now = new Date().toISOString();

function detectCategory(filename) {
  const name = (filename || "").toLowerCase();
  const tokens = name.split(/[^a-z0-9]+/);
  // short keywords (hr, seo, rag, crm) must match a whole word, otherwise "through" => HR, "storage" => RAG
  const has = (k) => k.length <= 3 ? tokens.includes(k) : name.includes(k);

  if (has("crm")) return "CRM";
  if (has("sales")) return "Sales";
  if (has("finance")) return "Finance";
  if (has("invoice")) return "Invoice";
  if (has("hr")) return "HR";
  if (has("resume")) return "HR";
  if (has("youtube")) return "YouTube";
  if (has("seo")) return "SEO";
  if (has("marketing")) return "Marketing";
  if (has("rag")) return "RAG";
  if (has("chatbot")) return "RAG";
  if (has("health")) return "Healthcare";
  if (has("medical")) return "Healthcare";
  if (has("real_estate")) return "Real Estate";
  if (has("property")) return "Real Estate";
  if (has("legal")) return "Legal";
  if (has("contract")) return "Legal";
  if (has("education")) return "Education";
  if (has("student")) return "Education";
  if (has("manufacturing")) return "Manufacturing";
  if (has("logistics")) return "Logistics";
  if (has("supply")) return "Logistics";
  if (has("bank")) return "Banking";
  if (has("cyber")) return "Cybersecurity";
  if (has("hotel")) return "Hospitality";
  if (has("hospitality")) return "Hospitality";
  if (has("telecom")) return "Telecom";
  if (has("e-commerce")) return "E-commerce";
  if (has("shopify")) return "E-commerce";
  if (has("woocommerce")) return "E-commerce";

  return "General AI Automation";
}

return items.map(item => {

  const filename = item.json.filename || "Unknown.pdf";
  const workflowName = filename.replace(/\.pdf$/i, "");
  const category = detectCategory(filename);

  return {
    json: {

      // ==========================
      // Identity
      // ==========================
      document_id: `${workflowName}_chunk_${item.json.chunk_index}`,
      workflow_name: workflowName,
      project_name: workflowName,
      filename: filename,

      // ==========================
      // Classification
      // ==========================
      category: category,
      niche: category,

      // ==========================
      // Search Metadata
      // ==========================
      tags: [],
      keywords: [],
      status: "active",

      // ==========================
      // Source Information
      // ==========================
      source: "Workflow Knowledge Base",
      document_type: "workflow",
      language: "en",

      // ==========================
      // Chunk Information
      // ==========================
      chunk_index: item.json.chunk_index,
      total_chunks: item.json.total_chunks,
      chunk_length: item.json.chunk_length,

      // ==========================
      // Workflow Content
      // ==========================
      text: item.json.text,

      // ==========================
      // Embedding Information
      // ==========================
      embedding_model: "models/gemini-embedding-001",
      vector_provider: "Google Gemini",

      // ==========================
      // Future Market Intelligence
      // (Workflow 3 will update these)
      // ==========================
      project_rate: null,
      fiverr_demand: null,
      upwork_demand: null,
      business_value: null,
      difficulty: null,
      estimated_hours: null,
      automation_level: null,
      market_reason: null,

      // ==========================
      // Version Information
      // ==========================
      version: "3.0",
      metadata_version: "3.0",

      created_at: now,
      updated_at: now

    }
  };
});

const chunkSize = 1000;
const overlap = 200;
const output = [];

for (const item of $input.all()) {
  const text = item.json.text || "";
  const filename = item.json.filename || "Unknown.pdf";
  const fileChunks = [];
  let start = 0;
  let chunkIndex = 1;

  while (start < text.length) {
    const chunk = text.slice(start, start + chunkSize);
    fileChunks.push({ filename, chunk_index: chunkIndex, chunk_length: chunk.length, text: chunk });
    if (start + chunkSize >= text.length) break; // last chunk reached: don't emit a tiny duplicate tail
    start += chunkSize - overlap;
    chunkIndex++;
  }

  // total_chunks is now exact (the old formula was an estimate)
  for (const c of fileChunks) output.push({ json: { ...c, total_chunks: fileChunks.length } });
}

return output;

const items = $input.all();

return items.map(item => {

  let text = item.json.text || "";

  text = text.replace(/\s+/g, " ");
  text = text.replace(/\n\s*\n/g, "\n");
  text = text.trim();

  return {
    json: {
      filename: item.json.filename,
      text
    }
  };

});

const vector = $json.embedding?.values;

if (!vector || !Array.isArray(vector)) {
  throw new Error("Embedding vector not found.");
}

// Get ALL metadata from previous node
const metadata = $("Code (Build Gemini Payload)").item.json;

// Remove Gemini request payload
const output = { ...metadata };
delete output.payload;

// Add vector information
output.vector = vector;
output.vector_dimension = vector.length;

return {
  json: output
};

return {
  json: {
    ...$json,

    payload: {
      model: "models/gemini-embedding-001",
      content: {
        parts: [
          {
            text: $json.text
          }
        ]
      }
    }
  }
};

// Deterministic UUID from document_id.
// (Old logic summed char codes -> "x_chunk_12" and "x_chunk_21" collided and silently overwrote each other.)
function hash32(str, seed) {
  let h = seed >>> 0;
  for (let i = 0; i < str.length; i++) {
    h = Math.imul(h ^ str.charCodeAt(i), 2654435761);
    h ^= h >>> 15;
  }
  return h >>> 0;
}
const s = String($json.document_id);
const hex = [1, 2, 3, 4].map(seed => hash32(s, seed).toString(16).padStart(8, "0")).join("");
const pointId = `${hex.slice(0, 8)}-${hex.slice(8, 12)}-5${hex.slice(13, 16)}-a${hex.slice(17, 20)}-${hex.slice(20, 32)}`;

// Copy all metadata except vector
const payload = { ...$json };
delete payload.vector;

// Nested copy so n8n's Qdrant Vector Store node (Project 14) can read metadata.workflow_name
payload.metadata = {
  workflow_name: payload.workflow_name,
  workflow_category: payload.category,
  category: payload.category,
  filename: payload.filename,
  document_id: payload.document_id,
  chunk_index: payload.chunk_index
};

return {
  json: {
    payload: {
      points: [{ id: pointId, vector: $json.vector, payload }]
    }
  }
};

